mapper.update:
UPDATE tianquan_oauth.oauth_security_state
SET generation = #{po.generation}, enabled = #{po.enabled}, revision = #{po.revision},
    reason_code = #{po.reasonCode}, version = #{po.version},
    update_user_id = #{po.updateUserId}, update_time = #{po.updateTime}
WHERE tenant_id = #{tenantId} AND id = #{po.id} AND target_type = #{po.targetType}
  AND target_key = #{po.targetKey} AND version = #{expectedVersion} AND deleted_at IS NULL

UPDATE tianquan_oauth.oauth_security_state
SET deleted_at = CURRENT_TIMESTAMP AT TIME ZONE 'UTC', version = version + 1,
    update_user_id = #{po.updateUserId}, update_time = #{po.updateTime}
WHERE tenant_id = #{tenantId} AND id = #{po.id}
  AND version = #{expectedVersion} AND deleted_at IS NULL
